Fixed. The three defects were: `Effect.fail(err)` narrowed `err` to `never`, `Effect.catchTag('NoFuel', …)` returns `never` so it can't be `yield*`'d directly, and `reportCredits` returned a nested `Effect<Effect<…>>`.

```ts
import {Effect, Either, Schedule, Schema} from 'effect';
import {
  orient, scout, goTo, mine, sell, service, prices, readMarket, salvage, hunt, disengage,
  missions, acceptMission, completeMissions, note, MarketBook,
} from 'play';

// Final act: always log current credits. orient() never fails; orDie just widens
// the error to unknown so the pipeline typechecks against the Game service.
const reportCredits = () =>
  orient().pipe(
    Effect.map(o => note(`credits: ${o.credits}`)),
    Effect.orDie,
  );

// Mine at the belt as many full-hold cycles as we can.
// HoldFull ends the run; InBattle is disengaged and retried; NotAtBelt stops.
// A plain function so the caller can decide what to do with a NoFuel stop.
const mineRun = () =>
  Effect.gen(function* () {
    while (true) {
      const step = yield* mine().pipe(
        Effect.catchTag('InBattle', () => disengage()),
        Effect.either,
      );
      if (Either.isRight(step)) continue;        // mined a cycle; go again
      const err = step.left;
      if (err._tag === 'HoldFull') break;         // the stop we wanted
      if (err._tag === 'NotAtBelt') break;        // can't mine anywhere
      return yield* Effect.fail(step.left);       // anything else: fail
    }
    return undefined;
  });

// "Mine until the hold is full", tolerating a fuel-starved turn: if we stop for
// NoFuel we don't fail — we proceed to the base, where the docked goTo resolves it.
const untilFull = () =>
  mineRun().pipe(
    Effect.catchTag('NoFuel', () => Effect.void),
  );

const atKepler = () =>
  Effect.gen(function* () {
    yield* goTo('kepler_base').pipe(Effect.retry({
      times: 5,
      schedule: Schedule.exponential('1 second'),
      while: e => e._tag === 'ServerBusy',
    }));
    yield* sell([{item_id: 'copper_ore'}]);   // only what we named
    yield* service();
    yield* completeMissions().pipe(
      Effect.catchTag('NothingCompletable', () => Effect.void),
    );
  }).pipe(Effect.ensuring(disengage()));

export default Effect.gen(function* () {
  yield* goTo('kepler_belt');
  yield* untilFull();
  yield* atKepler();
}).pipe(
  Effect.ensuring(reportCredits),   // the last thing, on success or failure
  Effect.orDie,                     // unhandled failures still fail the program
);
```

