The errors are all on `Effect.retry` — I was passing a `schedule` as a generator-Effect with an `Effect.sleep` inside it, which doesn't match the overloads. Dropping `times` and using a bare `Schedule.exponential` satisfies them.

```ts
import {Effect, Schedule} from 'effect';
import {orient, goTo, mine, sell, service, completeMissions, disengage, note} from 'play';

// If pirates engage, wait them out and retry with backoff.
const waitPirates = <A, E>(eff: Effect.Effect<A, E, import('play').Game>): Effect.Effect<A, E, import('play').Game> =>
  eff.pipe(Effect.retry({
    schedule: Schedule.exponential('1 second').pipe(Schedule.take(24)),
    while: e => e._tag === 'InBattle',
  }));

// Mine until the hold is full. If pirates engage, disengage and keep going.
const mineUntilFull = () =>
  Effect.gen(function* () {
    const res = yield* mine().pipe(Effect.either);
    if (res._tag === 'Right') return;
    switch (res.left._tag) {
      case 'InBattle':
        yield* disengage();
        break;
      case 'HoldFull':
        return;
    }
    return yield* Effect.fail(res.left);
  });

// Mine the remainder of the hold (do NOT re-flake: a fresh flake drops below 10 and loops).
const mineRest = () =>
  Effect.gen(function* () {
    const p = yield* orient();
    if (p.cargo_used < p.cargo_capacity) {
      return yield* mineUntilFull();
    }
  });

// The haul: fly to kepler_belt, mine to full, fly to kepler_base, sell the copper.
const haulCycle = () =>
  Effect.gen(function* () {
    yield* goTo('kepler_belt');
    yield* mineUntilFull();
    yield* goTo('kepler_base');
    yield* sell([{item_id: 'copper_ore'}]);
  });

// Re-arrive at the belt; repair at base first only if the hull is really hurt.
const reBeltCycle = () =>
